  "type": "expression_regulation_down",
  "directed": "true",
  "mechanism": "HEY1 is induced by Notch1 activation and reproduces its effect on Orai1 and Orai3 in MCF10A, MDA-MB-231 and MCF7 cells; the phosphomimetic HEY1 S68D mutant cannot repress them, unlike wild type and the non-phosphorylatable S68A, so phosphorylation at Ser-68 switches the repression off | the authors name the axis they establish - Notch1 to HEY1 to the Orai channels - and tie it to SOCE; kept as a second evidence row because the substantive sentence above names no calcium term, and the map's inclusion rule needs one somewhere on the node",
  "n_sources": "1",
  "n_pubs": "1",
  "n_db": "0",
  "n_curated": "0",
  "has_human_evidence": "true",
  "has_animal_evidence": "false",
  "calcium_evidence": "GO+text+curated",
  "beyond_calcium": "false",
  "string_score": "",
  "justification": "The transcriptional repressor between NOTCH1 and the channels, with a phospho-site that controls whether it works. It turns a receptor-to-channel correlation into a two-step mechanism the map can draw. | The sentence that states the axis as a whole, and the one that carries the calcium criterion for HEY1. Without it the repressor would be dropped from the map although it is the mechanism of the NOTCH1 edges.",
