  "mechanism": "the elevated ORAI1-mediated SOCE of cystic fibrosis airway epithelia roughly doubles interleukin-8 secretion; the chain is CFTR absent at the surface -> more ORAI1 inserted -> more SOCE -> more IL-8 | same silencing experiments; histamine is the stimulus and the readout is secreted interleukin-8 | same cisplatin and BTP2 experiment | shRNA against ORAI1 in LAD2 cells partly blocks substance-P-induced IL-8 release measured by ELISA, and Synta66 abrogates it; the knockdowns of ORAI2 and ORAI3 do the same, so the three channels are not redundant here",
