  "string_score": "",
  "justification": "An effector end for the ORAI1 arm in a chronic inflammatory disease, beside ORAI1 -> IL6 (batch 10) and ORAI1/STIM1 -> TNF (batch 11). The cytokines the channel controls are becoming a coherent group. | A second, independent evidence row on the ORAI1 -> IL8 edge the map already carries, in a different tissue. | A third independent paper on ORAI1 -> IL8, after the cystic fibrosis epithelium (batch 13) and histamine-stimulated endothelium (batch 14). Three tissues, three stimuli, one cytokine. | A third cell type for the TNF/IL-8 arm and a new chemokine, CCL3, at the effector end.",
  "conflict_with": "",
