  "target": "ITPR1",
  "type": "activation",
  "directed": "true",
  "mechanism": "the GPR40 agonist fasiglifam potentiates glucose-induced insulin secretion in MIN6 cells and that potentiation disappears when ITPR1 is knocked down; beta-cell-specific Stim1 knockout mice lose it in islets and in vivo, and STIM1 or ORAI1 knockdown also removes the agonist's SOCE and Ca2+ rise",
  "n_sources": "1",
  "n_pubs": "1",
  "n_db": "0",
