  "mechanism": "co-immunoprecipitation of the STIM1/TRPC1 complex in intestinal epithelial cells; STIM1 silencing reduces store-operated Ca2+ influx and epithelial restitution | same binding panel: STIM1 binds TRPC1 directly, which is the opposite of the mesangial-cell result where STIM1 co-immunoprecipitated with TRPC4 and not TRPC1 | store depletion drives STIM1 to the platelet surface and into association with endogenous TRPC1; an anti-STIM1 antibody against the N-terminal Ca2+-binding region blocks the migration, the STIM1-TRPC1 association and SOCE, and the association needs an intact actin cytoskeleton | co-immunoprecipitation from mouse myocardium with an anti-STIM1 antibody; doxorubicin lowers STIM1 abundance and with it the amount of ORAI1 and TRPC1 pulled down, while ORAI1 and TRPC1 levels stay unchanged | the same ternary co-immunoprecipitation in human parathyroid tissue",
