  "justification": "A functional reference for the STIM1-TRPC1 complex outside the usual cell lines, tying it to epithelial wound repair. | Recorded deliberately next to PMID 19307462, which says STIM1 binds TRPC4 but not TRPC1: the same question answered both ways in different cells. | The STIM1-TRPC1 binding shown on endogenous proteins in human platelets, not on overexpressed constructs, and the paper that first reported it. It also dates the claim: 2006, before most of the STIM1-TRPC1 literature the map carries. | The STIM1-TRPC1 complex in a whole animal heart rather than a cell line, and a demonstration that the complex is a dose-dependent quantity: lose STIM1 to a drug and the partnership drops with it, which is how the doxorubicin cardiotoxicity in this paper gets its ER stress. | Second arm of the same complex, in the same human tissue.",
