  "mechanism": "in HUVECs stimulated with septic serum or LPS, RNAi against STIM1 inhibits calcium influx and the expression of TNF, ICAM1 and endothelin-1; STIM1 overexpression promotes the same cytokines | with store depletion rather than LPS as the stimulus, STIM1 knockdown does reduce TNF-alpha and IL-6 release; neither knockdown affected the loss of cell viability, so the cytokine arm is separable from the toxicity | conditional Stim1/Stim2 knockout in T cells: cytotoxic lymphocytes lose degranulation and TNF-alpha production, and the mice fail to control melanoma and colon carcinoma engraftment. Both sensors are deleted together",
